95	function startOfWeek(date = new Date()) {
96	  const d = new Date(date);
97	  const day = d.getDay();
98	  const diff = (day === 0 ? -6 : 1) - day;
99	  d.setDate(d.getDate() + diff);
100	  d.setHours(0, 0, 0, 0);
101	  return d;
102	}
103	
104	function formatDateISO(d: Date) {
105	  const y = d.getFullYear();
106	  const m = String(d.getMonth() + 1).padStart(2, '0');
107	  const day = String(d.getDate()).padStart(2, '0');
108	  return `${y}-${m}-${day}`;
109	}
110	
111	function parseISODateLocal(iso: string) {
112	  if (!iso) return new Date();
113	  const [y, m, d] = iso.split('-').map(Number);
114	  return new Date(y, (m || 1) - 1, d || 1);
115	}
