206	export default function EventosTimeline() {
207	  const isMobile = useIsMobile();
208	  const navigate = useNavigate();
209	  const { selectedStore, stores } = useStore();
210	  const telemetryAttrs = useTelemetryAttrs();
211	  const [items, setItems] = useState<TimelineItem[]>([]);
212	  const [loading, setLoading] = useState(true);
213	  const [isCreateOpen, setIsCreateOpen] = useState(false);
214	  const [detailsItem, setDetailsItem] = useState<TimelineItem | null>(null);
215	  const [mobileSelectedDate, setMobileSelectedDate] = useState<string>(
216	    formatDateISO(new Date()),
217	  );
218	
219	  // Filters
220	  const [typeFilter, setTypeFilter] = useState<
221	    'todos' | 'evento' | 'encomenda_pj'
222	  >('todos');
223	  const [statusFilter, setStatusFilter] = useState<
224	    'todos' | 'aberto' | 'finalizado'
225	  >('aberto');
226	
227	  // Search (eventos + PJ, sem limite de data) — útil pra resgatar pedidos antigos
228	  const [searchTerm, setSearchTerm] = useState('');
229	  const [isSearchFocused, setIsSearchFocused] = useState(false);
230	
231	  const searchResults = useMemo<TimelineItem[]>(() => {
232	    const q = searchTerm.trim().toLowerCase();
233	    if (q.length < 2) return [];
234	
235	    const normalize = (v: unknown) =>
236	      String(v ?? '')
237	        .toLowerCase()
238	        .normalize('NFD')
239	        .replace(/[̀-ͯ]/g, '');
240	    const needle = normalize(q);
241	
242	    const matches = items.filter((item) => {
243	      const fields =
244	        item.type === 'evento'
245	          ? [
246	              item.nome,
247	              item.endereco,
248	              item.responsavel,
249	              item.telefone_responsavel,
250	              item.observacoes,
251	              item.data_inicio,
252	              item.id,
253	            ]
254	          : [
255	              item.cliente_nome,
256	              item.cliente_endereco,
257	              item.cliente_telefone,
258	              item.pedido_descricao,
259	              item.observacao,
260	              item.forma_pagamento,
261	              item.data_entrega,
262	              item.id,
263	            ];
264	      return fields.some((f) => normalize(f).includes(needle));
265	    });
266	
267	    return matches
268	      .slice()
269	      .sort((a, b) => {
270	        const da = a.type === 'evento' ? a.data_inicio : a.data_entrega;
271	        const db = b.type === 'evento' ? b.data_inicio : b.data_entrega;
272	        return (db || '').localeCompare(da || '');
273	      })
274	      .slice(0, 30);
275	  }, [items, searchTerm]);
276	
277	  const [createType, setCreateType] = useState<'evento' | 'encomenda_pj'>(
278	    'evento',
279	  );
280	
281	  // Budget Generator State
282	  const [isBudgetGeneratorOpen, setIsBudgetGeneratorOpen] = useState(false);
283	  const [budgetGenForm, setBudgetGenForm] = useState({
284	    clientName: '',
285	    address: '',
