-- Liga todas as ocorrências de uma encomenda recorrente.
-- Cada ocorrência futura é uma row independente em `encomendas` (1 row = 1 entrega),
-- mas compartilham `recorrencia_grupo_id` pra ações em série (finalizar/excluir todas).
ALTER TABLE encomendas
  ADD COLUMN IF NOT EXISTS recorrencia_grupo_id UUID NULL;

CREATE INDEX IF NOT EXISTS idx_encomendas_recorrencia_grupo
  ON encomendas (recorrencia_grupo_id)
  WHERE recorrencia_grupo_id IS NOT NULL;

COMMENT ON COLUMN encomendas.recorrencia_grupo_id IS
  'UUID que liga todas as ocorrências de uma mesma encomenda recorrente. NULL em pedidos não recorrentes.';

-- Quantidade de kits por encomenda (pode pedir 2 kits na mesma encomenda)
ALTER TABLE public.encomendas
  ADD COLUMN IF NOT EXISTS kit_quantidade integer DEFAULT 1;

-- Atualiza RPC para aceitar quantidade variável (antes subtraía sempre 1)
CREATE OR REPLACE FUNCTION public.movimentar_kit_encomenda(
  p_produto_master_id integer,
  p_loja_id integer,
  p_tipo text,
  p_motivo text,
  p_quantidade numeric DEFAULT 1
) RETURNS numeric
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  qtd_atual numeric;
  qtd_nova  numeric;
BEGIN
  SELECT COALESCE(quantidade_atual, 0) INTO qtd_atual
  FROM public.estoque
  WHERE produto_master_id = p_produto_master_id
    AND loja_id = p_loja_id
  FOR UPDATE;

  IF p_tipo = 'saida' THEN
    qtd_nova := qtd_atual - p_quantidade;
    IF qtd_nova < 0 THEN
      RAISE EXCEPTION 'Estoque insuficiente de kit (disponível: %, solicitado: %)', qtd_atual, p_quantidade;
    END IF;
  ELSE
    qtd_nova := qtd_atual + p_quantidade;
  END IF;

  INSERT INTO public.movimentacoes (
    produto_master_id, loja_id, tipo_movimentacao,
    quantidade, quantidade_anterior, quantidade_nova, motivo
  ) VALUES (
    p_produto_master_id, p_loja_id, p_tipo,
    p_quantidade, qtd_atual, qtd_nova, p_motivo
  );

  RETURN qtd_nova;
END;
$$;

-- Realtime: outros usuários veem a contagem atualizar quando alguém cria uma encomenda com kit
-- estoque já está na publication supabase_realtime
ALTER TABLE public.estoque REPLICA IDENTITY FULL;

